previewCss:
.darma-loader-darma-b7-coin-flip { --accent: var(--loader-color, #eab308); --accent-2: var(--loader-secondary-color, #b45309); width: var(--loader-size, 72px); height: var(--loader-size, 72px); position: relative; perspective: 600px; }
.darma-loader-darma-b7-coin-flip span { position: absolute; inset: 16%; border-radius: 50%; transform-style: preserve-3d; animation: darma-loader-darma-b7-coin-flip-coin calc(var(--loader-speed, 1s) * 1.6) linear infinite; }
.darma-loader-darma-b7-coin-flip span::before, .darma-loader-darma-b7-coin-flip span::after { content: ''; position: absolute; inset: 0; border-radius: 50%; backface-visibility: hidden; }
.darma-loader-darma-b7-coin-flip span::before { background: radial-gradient(circle at 35% 30%, color-mix(in srgb, #fff 40%, var(--accent)), var(--accent)); }
.darma-loader-darma-b7-coin-flip span::after { background: radial-gradient(circle at 35% 30%, color-mix(in srgb, #fff 40%, var(--accent-2)), var(--accent-2)); transform: rotateY(180deg); }
@keyframes darma-loader-darma-b7-coin-flip-coin { to { transform: rotateY(360deg); } }

